// The C++ frame encoder must give byte-for-byte what the Python reference gives
// (golden_uart.txt, generated by tools/golden/gen_golden.py from UartInterface.create_message).
#include <gtest/gtest.h>

#include <fstream>
#include <sstream>
#include <string>

#include "buggy_core/actuation/uart_frame.hpp"

#ifndef GOLDEN_DIR
#define GOLDEN_DIR "."
#endif

TEST(UartFrame, MatchesPythonReference)
{
  std::ifstream f(std::string(GOLDEN_DIR) + "/golden_uart.txt");
  ASSERT_TRUE(f.good()) << "run tools/golden/gen_golden.py first";
  std::string line;
  int checked = 0;
  while (std::getline(f, line)) {
    if (line.empty() || line[0] == '#') {continue;}
    std::istringstream ss(line);
    double angle;
    int y, r, b[6];
    ss >> angle >> y >> r;
    for (int & v : b) {ss >> v;}
    const auto frame = buggy_core::encode_frame(y != 0, r != 0, angle);
    for (int i = 0; i < 6; ++i) {
      EXPECT_EQ(static_cast<int>(frame[i]), b[i]) << "angle " << angle << " yellow " << y
                                                  << " red " << r << " byte " << i;
    }
    ++checked;
  }
  EXPECT_EQ(checked, 72);
}

TEST(UartFrame, StopFrameIsRedAndCentred)
{
  const auto f = buggy_core::encode_frame(false, true, 0.0);
  EXPECT_EQ(f[0], 40);
  EXPECT_EQ(f[1], 0);
  EXPECT_EQ(f[2], 1);
  const int raw = (f[3] << 8) | f[4];
  EXPECT_EQ(raw, 3000);        // (0 + 30) / 0.01
  EXPECT_EQ(f[5], 41);
}

// ---- sign convention on the wire: raw = (deg + 30) / 0.01, so LEFT (negative) < 3000 < RIGHT (positive)
TEST(UartFrameSigns, LeftIsBelowCentreRightIsAbove)
{
  const auto raw = [](double deg) {
      const auto f = buggy_core::encode_frame(false, false, deg);
      return static_cast<int>(static_cast<int16_t>((f[3] << 8) | f[4]));
    };
  EXPECT_EQ(raw(0.0), 3000);
  EXPECT_EQ(raw(-10.0), 2000);               // 10 deg LEFT
  EXPECT_EQ(raw(+10.0), 4000);               // 10 deg RIGHT
  EXPECT_EQ(raw(-20.0), 1000);
  EXPECT_EQ(raw(+20.0), 5000);
  EXPECT_EQ(raw(+90.0), 5000);               // clamped
  EXPECT_EQ(raw(-90.0), 1000);
}
